scwin.fn_sync = function(dtsObj, searchType, year) {
    // 회사별 보고서 조회
    var url = "/EsgSearch.do?method=companyByAllReport";
    url += "&YEAR=" + year; // 연도
    url += "&SEARCH_TYP=" + searchType; // 조회구분
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd); //법인코드

    // 로딩 이미지가 순식간에 나타났다 사라지거나 로딩 이미지가 그려지는 영역은 보여지는데 이미지 자체가 안보이는 경우가 있어서 1초 간격을 줌.
    setTimeout(function() {
        // dataset별로 grid가 하나씩 매핑 되어야 하고, grid 개수만큼 메서드가 호출 되어야함.
        dtsObj.DataID = url;
        dtsObj.Reset();
    }, 1000);
};
scwin.fn_ExcelDown = function() {
