        } else if (colid == "SUPLMNT_DSC") {
            reqElmtId = "krx-cg_FutureActionPlansAndSupplementaryExplanationsRegardingPerformingAuditRelatedTasksByTheInternalAuditTeamExplanatory";
        }
    }
    // 세부원칙 10-1
    if (scwin.dtlRoleSel == 'role10-1') {
        if (colid == "ROLE_10_1_DSC") {
