        } else if (colid == "EXT_AUDTR_EXEC_DSC") {
            reqElmtId = "krx-cg_EvaluationAndContentsOfExternalAuditorsAfterCompletionOfExternalAuditExplanatory";
        } else if (colid == "EXT_AUDTR_CONSULT_RSN") {
            reqElmtId = "krx-cg_DetailsOfTheReasonsAndExpensesPaidForConsultingOrNonAuditServicesProvidedByExternalAuditorsAndItsSubsidiariesExplanatory";
        } else if (colid == "LACK_RSN") {
            reqElmtId = "krx-cg_ExplanationOfDeficienciesAndTheReasonsThereofRegardingThePolicyToSecureIndependenceAndExpertiseWhenAppointingExternalAuditorsExplanatory";
        } else if (colid == "SUPLMNT_DSC") {
            reqElmtId = "krx-cg_FutureActionPlansAndSupplementaryExplanationsRegardingThePolicyToSecureIndependenceAndExpertiseWhenAppointingExternalAuditorsExplanatory";
        }
    }
    // 세부원칙 10-2
    if (scwin.dtlRoleSel == 'role10-2') {
        if (colid == "ROLE_10_2_DSC") {
            reqElmtId = "krx-cg_WhetherTheInternalAuditorsConstantlyCommunicatedWithTheExternalAuditorInEveryStageOfExternalAuditAndReportingOfResultsOrNot";
        } else if (colid == "BYQTR_OVR1_AUDT_NEGO_DSC") {
            reqElmtId = "krx-cg_DiscussionOnMajorIssuesRelatedToExternalAuditingMoreThanOncePerQuarterWithoutExecutivePresenceExplanatory";
        } else if (colid == "AUDT_BZ_APPL_PROCS_CONTN") {
            reqElmtId = "krx-cg_MajorDetailsOfDiscussionsAndReflectionOnInternalAuditingExplanatory";
        } else if (colid == "INSIDE_AUDT_ROLE_RESPBL") {
