scwin.dts_role000002_OnLoadCompleted = async function(rowcount) {
    // 원칙별로 한번에 조회를 하지만 결과 처리는 기업개요 조회에서만 함

    $c.cm.CloseWin(rowcount, role000003_Grid); //조회완료시 LOADING 이미지 종료			

    if (rowcount == 0) {
        setTimeout(function() {
            // 데이타가 없을 경우 결과 문구 노출 후 문구를 2초후 안보이게 해줌
            if ($c.frame.path("NoData") != null) {
                await $c.frame.CloseFrame();
            }
        }, 2000);
    }
    // 조회가 끝나면 조회 버튼 활성화 
    scwin.clickPossible = "true";
};
scwin.gform_onload = function() {
    Grd_com_isur.style.zIndex = 30;
    $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.initPage();
};
scwin.dts_year_OnLoadCompleted = function(rowcount) {
    // 연도가 없다는건 등록 된 데이타가 없다는 것이기 때문에 별도 텍스트를 보여줌
    if (rowcount == 0) {
        dts_year.insertRow();
        dts_year.setCellData(1, "YEAR_TEXT", '연도가 존재하지 않습니다');
        dts_year.setCellData(1, "YEAR", '');
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
