scwin.viewer_btn_onclick = function() {
    var gAcptNo = dts_role000002.getCellData(1, "ACPT_NO"); // 접수번호
    // 회사별 보고서 조회를 하지 않았거나 조회 된 데이타가 없으면 버튼 클릭 시 아무런 액션을 하지 않음
    if (gAcptNo == null || gAcptNo == "undefined") {
        return;
    }
    // 공시뷰어 새창열기 버튼을 클릭할 경우 공시뷰어 메인창을 오픈
    $c.stf.fn_OpenDisclViewer(gAcptNo, "R");
};
